/**
 * 24dp·24 뷰포트 단색 아이콘 하나. SVG 경로 문자열은 Compose 의 파서가 그대로 읽는다.
 *
 * @param mirror 오른쪽·왼쪽을 가리키는 아이콘만 참. RTL 로케일에서 좌우가 뒤집힌다.
 */
private fun icon(pathData: String, mirror: Boolean = false): Lazy<ImageVector> = lazy {
    ImageVector.Builder(
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
        autoMirror = mirror,
    ).apply { addPath(addPathNodes(pathData), fill = SolidColor(Color.Black)) }.build()
}
